			if (currentCopy.color) if (sp.color) sp.color.copyFrom(currentCopy.color);
			else sp.color = currentCopy.color.clone();
			sp.scaling.copyFrom(currentCopy.scaling);
			sp.uvs.copyFrom(currentCopy.uvs);
			if (currentCopy.materialIndex !== null) sp.materialIndex = currentCopy.materialIndex;
			if (this.expandable) this._idxOfId[sp.id] = sp.idx;
